// SEND A WELCOME SEQUENCE TO NEW BREVO CONTACTS BASED ON SIGNUP SOURCE - CONFIG
// Edit values only in this node. Nothing else in this workflow needs changing.
// USE_BREVO false -> SAMPLE contacts.
// Sends go through the Brevo transactional API; WELCOME_STEP is written only on a live run.

// set true after adding the Brevo credential to the three Brevo nodes
const USE_BREVO = false;
// verified Brevo sender
const SENDER = {
  name: "Mara at Tallyroom",
  email: "hello@yourcompany.example"
};
// days after signup for steps 1, 2 and 3
const SEQUENCE_DAYS = [
  0,
  2,
  5
];
// SOURCE attribute value (lowercase) -> variant; anything else uses default
const SOURCE_MAP = {
  trial: "trial",
  "free-trial": "trial",
  webinar: "webinar",
  ebook: "content",
  guide: "content",
  checklist: "content"
};
// per variant: one entry per step with subject and opening line (avoid apostrophes)
const SEQUENCES = {
  trial: [
    {
      subject: "Your trial is ready, here is the 5-minute setup",
      line: "Most teams are set up after three steps: invite one colleague, connect a card and upload last month of receipts."
    },
    {
      subject: "The one report trial users open most",
      line: "The spend-by-person report shows where the money went last month, and it fills itself once receipts are in."
    },
    {
      subject: "Questions before your trial ends?",
      line: "Reply to this email with anything that is not working. A person reads every reply within one working day."
    }
  ],
  webinar: [
    {
      subject: "Thanks for registering, here is what to expect",
      line: "You will get the join link an hour before we start. Bring one question about your month-end process."
    },
    {
      subject: "The checklist from the session",
      line: "This is the month-end checklist we walked through, ready to copy."
    },
    {
      subject: "Want to try it on your own numbers?",
      line: "A free trial takes five minutes to set up and you can import last month to compare."
    }
  ],
  content: [
    {
      subject: "Your download is inside",
      line: "Here is the link to the guide you asked for. It takes about 12 minutes to read."
    },
    {
      subject: "Three templates that go with the guide",
      line: "These are the expense policy, approval rules and reimbursement templates referenced in chapter two."
    },
    {
      subject: "How one 12-person team uses it",
      line: "Northwind Labs cut their close from six days to two with the steps in the guide."
    }
  ],
  default: [
    {
      subject: "Welcome to Tallyroom",
      line: "Thanks for signing up. Here is where to start."
    },
    {
      subject: "Three things worth setting up first",
      line: "Invite a colleague, connect a card and set one approval rule."
    },
    {
      subject: "Anything we can help with?",
      line: "Reply to this email and a person will answer within one working day."
    }
  ]
};
// contacts older than this with no step sent never start (protects existing contacts on day one)
const START_WITHIN_DAYS = 1;
// hard ceiling on emails per run
const DAILY_CAP = 100;
// your unsubscribe page; the contact email is appended as ?email=
const UNSUBSCRIBE_URL = 'https://www.yourcompany.example/unsubscribe';
// ships true. Nothing reaches a real recipient or system.
const TEST_RUN = true;
// blank -> preview only. Set -> sends go here instead. Never causes a send on its own.
const TEST_EMAIL = '';

const MODE = TEST_RUN !== true ? 'live' : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');

return [{
  json: {
    use_brevo: USE_BREVO,
    sender: SENDER,
    sequence_days: SEQUENCE_DAYS,
    source_map: SOURCE_MAP,
    sequences: SEQUENCES,
    start_within_days: START_WITHIN_DAYS,
    daily_cap: DAILY_CAP,
    unsubscribe_url: UNSUBSCRIBE_URL,
    test_run: TEST_RUN,
    test_email: TEST_EMAIL,
    mode: MODE,
    live: MODE === 'live',
    sends_enabled: MODE !== 'preview',
    run_started_at: new Date().toISOString()
  }
}];

// Brevo /contacts -> flat contacts with the two attributes the sequence uses.
const out = [];
for (const page of $input.all()) for (const c of page.json.contacts || []) out.push({
  email: c.email, first_name: c.attributes?.FIRSTNAME || '', source: String(c.attributes?.SOURCE || ''), step: Number(c.attributes?.WELCOME_STEP || 0),
  created_at: c.createdAt, unsubscribed: Boolean(c.emailBlacklisted) });
return [{ json: { contacts: out } }];

// Used until USE_BREVO is true. One contact per sequence decision.
const ago = d => new Date(Date.now() - d * 864e5).toISOString();
return [{ json: { contacts: [
  { email: 'ana@northwind-labs.example', first_name: 'Ana', source: 'Trial', step: 0, created_at: ago(0.1), unsubscribed: false },
  { email: 'ben@harbourdesign.example', first_name: 'Ben', source: 'webinar', step: 1, created_at: ago(2.2), unsubscribed: false },
  { email: 'cai@pineco.example', first_name: 'Cai', source: 'ebook', step: 2, created_at: ago(5.5), unsubscribed: false },
  { email: 'dee@lumenphysio.example', first_name: 'Dee', source: 'trial', step: 2, created_at: ago(3), unsubscribed: false },
  { email: 'eve@orchardlane.example', first_name: 'Eve', source: 'trial', step: 0, created_at: ago(0.5), unsubscribed: true },
  { email: 'fin@northfield.example', first_name: 'Fin', source: 'podcast', step: 0, created_at: ago(6), unsubscribed: false },
  { email: 'gia@studio.example', first_name: '', source: 'partner', step: 0, created_at: ago(0.2), unsubscribed: false },
] } }];

// One step per contact per run: the first step after WELCOME_STEP whose day has
// arrived. A contact who never got step 1 and is older than START_WITHIN_DAYS
// was there before the sequence and is left alone.
const cfg = $('config').first().json;
const days = cfg.sequence_days;
const due = [], held = [];
for (const c of $input.first().json.contacts) {
  const age = (Date.now() - new Date(c.created_at).getTime()) / 864e5;
  const variant = cfg.source_map[c.source.trim().toLowerCase()] || 'default';
  const next = c.step + 1;
  const reason =
    c.unsubscribed ? 'unsubscribed or blocked' :
    next > days.length ? 'sequence finished' :
    c.step === 0 && age > cfg.start_within_days ? 'joined before the sequence started' :
    age < days[next - 1] ? 'step ' + next + ' due in ' + Math.ceil(days[next - 1] - age) + ' day(s)' : '';
  if (reason) { held.push({ email: c.email, reason }); continue; }
  due.push({ ...c, variant, next_step: next, age_days: Math.floor(age) });
}
due.sort((a, b) => a.next_step - b.next_step || b.age_days - a.age_days);
for (const d of due.slice(cfg.daily_cap)) held.push({ email: d.email, reason: 'over DAILY_CAP, next run' });
return [{ json: { emails: due.slice(0, cfg.daily_cap), held } }];

// Subject and opening line from SEQUENCES, the rest is a fixed frame. Builds the
// Brevo /smtp/email payload; test mode sends to TEST_EMAIL with the real address in the subject.
const cfg = $('config').first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
return $input.all().map(({ json: c }) => {
  const copy = cfg.sequences[c.variant][c.next_step - 1];
  const to = cfg.mode === 'test' ? cfg.test_email : c.email;
  const html = '<p>Hi ' + esc(c.first_name || 'there') + ',</p><p>' + esc(copy.line) + '</p><p>' + esc(cfg.sender.name) + '</p>' +
    '<p style="font-size:12px;color:#777">You are getting this because you signed up. <a href="' + cfg.unsubscribe_url + '?email=' + encodeURIComponent(c.email) + '">Unsubscribe</a></p>';
  return { json: { email: c.email, step: c.next_step, variant: c.variant, subject: copy.subject, payload: {
    sender: cfg.sender, to: [{ email: to, name: c.first_name || undefined }],
    subject: (cfg.mode === 'test' ? '[TEST to ' + c.email + '] ' : '') + copy.subject, htmlContent: html,
    tags: ['welcome', 'welcome-' + c.variant, 'welcome-step-' + c.next_step] } } };
});
